import React from "react";
import { Navigate } from "react-router-dom";
import { auth } from "../firebase"; // Ensure correct path
import { useAuthState } from "react-firebase-hooks/auth"; 

const ProtectedRoute = ({ children }) => {
  const [user, loading] = useAuthState(auth); // Get Firebase auth state

  if (loading) return <p>Loading...</p>; // Prevent UI flashing
  if (!user) return <Navigate to="/auth/login" replace />; // Redirect if not logged in

  return children; // Show page if authenticated
};

export default ProtectedRoute;
